// Keeps the 3D game on the phone so it opens quickly and plays offline.
// (Named "sa3d-" so the 2D game's own clean-up never touches it.)
const CACHE = "sa3d-v43";
const SHELL = ["./", "index.html", "scene-polish.js?v=1", "features.js?v=1", "phase7m.js?v=3", "game.js?v=25", "analytics.js?v=3", "perf.js?v=1", "cow3d.js?v=5", "live3d.js?v=2", "sheep3d.js", "horse3d.js", "dog3d.js", "cat3d.js", "chicken3d.js", "farmer3d.js", "quadruped3d.js", "characters3d.html", "manifest.webmanifest", "lib/three.module.min.js", "lib/three.core.min.js", "art/authored-hands.js?v=2", "assets/hands/hands-candidate.glb?v=2", "lib/addons/loaders/GLTFLoader.js", "lib/addons/utils/BufferGeometryUtils.js", "lib/addons/utils/SkeletonUtils.js"];


self.addEventListener("install", (e) => {
  e.waitUntil(caches.open(CACHE).then((c) => c.addAll(SHELL)).then(() => self.skipWaiting()));
});
self.addEventListener("activate", (e) => {
  e.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((k) => k.startsWith("sa3d-") && k !== CACHE).map((k) => caches.delete(k))))
    .then(() => self.clients.claim()));
});
// The page and its code: network first, so updates show up right away. Pictures, textures and the 3D engine: from the phone first
// (they rarely change), refreshed in the background.
self.addEventListener("fetch", (e) => {
  const url = new URL(e.request.url);
  if (e.request.method !== "GET" || url.origin !== self.location.origin) return;
  const heavy = /\/(lib|art|tex|assets)\//.test(url.pathname);
  const fromNet = () => fetch(e.request).then((res) => { if (res.ok) { const copy = res.clone(); caches.open(CACHE).then((c) => c.put(e.request, copy)); } return res; });
  e.respondWith(heavy
    ? caches.match(e.request).then((hit) => { const net = fromNet().catch(() => hit); return hit || net; })
    : fromNet().catch(() => caches.match(e.request).then((r) => r || caches.match("index.html"))));
});

// a full farm save (JSON text). Firestore's own limit is 1 MiB per document; stay well under it.
function saveText(v) { return str(v, 2, 900000); }

// ---------- farms/{uid}: the cloud save. Only that account, never anyone else. ----------
// auth.js writes {save, level, coins, rev, updatedAt} in a transaction and always sets rev to the stored rev + 1.
match /farms/{uid} {
  allow get: if isMe(uid);
  // no list, not even for the owner: a count needs list permission, and list returns every player's whole save
  // (players.html's farm count then falls back to the presence count)
  allow list: if false;
  allow create, update: if isMe(uid)
    && hasExactly(['save', 'level', 'coins', 'rev', 'updatedAt'])
    && saveText(data().save)
    && num(data().level, 1, 100000) && num(data().coins, -1000000000000000, 1000000000000000)
    && data().rev == (resource == null ? 0 : resource.data.get('rev', 0)) + 1
    && millis(data().updatedAt);
  allow delete: if false;
}

// ---------- presence/{uid}: "seen" heartbeat for the owner's dashboard ----------
// auth.js: setDoc(presence/uid, {seen: serverTimestamp(), level, joined}, {merge: true})
match /presence/{uid} {
  allow read: if isOwner();
  allow create, update: if isMe(uid)
    && data().keys().hasOnly(['seen', 'level', 'joined'])
    && data().seen == request.time
    && num(data().level, 1, 100000)
    && (!('joined' in data()) || data().joined == null || millis(data().joined));

// ---------- Phase 7I: the canonical farm economy. ONLY the server (Cloud Functions, admin access) writes these. ----------
// economy/{uid}: spendable coins and tradable items. Starts at 0 coins and nothing else; legacy save wealth is never copied.
