  allow get: if isMe(uid);
  allow list: if false;
  allow write: if false;
}
// ledger/{uid}/rows/{key}: one create-once row per accepted action (the key is the idempotency key)
match /ledger/{uid}/rows/{key} {
  allow get, list: if isMe(uid);
  allow write: if false;
}
